import heapq

def find_kth_largest(nums, k):
    pen = nums[:k]
    heapq.heapify(pen)              # min-heap of the k best so far
    for v in nums[k:]:
        if v > pen[0]:
            heapq.heapreplace(pen, v)
    return pen[0]

