#include <bits/stdc++.h>
using namespace std;

int findKthLargest(vector<int>& nums, int k) {
    priority_queue<int, vector<int>, greater<int>> pq;
    for (int i = 0; i < (int)nums.size(); ++i) {
        if ((int)pq.size() < k) { pq.push(nums[i]); continue; }
        if (nums[i] > pq.top()) { pq.pop(); pq.push(nums[i]); }
    }
    return pq.top();
}

