import java.util.PriorityQueue;

class Solution {
    public int findKthLargest(int[] nums, int k) {
        PriorityQueue<Integer> pq = new PriorityQueue<>();
        for (int v : nums) {
            if (pq.size() < k) { pq.offer(v); continue; }
            if (v > pq.peek()) { pq.poll(); pq.offer(v); }
        }
        return pq.peek();
    }
}
